docs.setup:
The consuming app must load the Google Maps Places library once at startup before using this component:

```ts
import { setOptions, importLibrary } from '@googlemaps/js-api-loader';

setOptions({ key: process.env.NEXT_PUBLIC_GOOGLE_API_KEY || '' });
importLibrary('places').catch(() => {});
```

Place this at module level (e.g. in a global context provider) so it runs exactly once.

docs.usage:
import * as LocationInput from "@/components/ui/location-input"

const [location, setLocation] = useState<LocationRequest>(null)

<LocationInput.Root
  location={location}
  onLocationChange={setLocation}
  placeholder="Search address..."
/>

examples.code:
const { setValue, watch } = useFormContext()

<FormField.Root name="location" label="Location" required>
  <LocationInput.Root
    location={
      watch('location')
        ? { formatted_address: watch('location') } as LocationRequest
        : null
    }
    onLocationChange={(loc) =>
      setValue('location', loc?.formatted_address ?? '', {
        shouldValidate: true,
      })
    }
  />
</FormField.Root>

